//go:build linux

package desktop

import (
	"embed"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// Icons are embedded rather than read from the source tree so a single
// installed binary can register itself on a machine that has no copy of
// the repository. They are generated by tray/icon/generate.go.
//
//go:embed icons/app*.png icons/godl.svg
var icons embed.FS

// entry is the .desktop file. The fields are the ones a launcher reads:
// Categories puts godl under Network/Utility rather than in an "Other"
// bucket, Keywords makes it findable by what people call it, and
// StartupNotify=false stops the shell showing a loading cursor for a
// window that never comes — godl opens a browser or a terminal, not a
// window of its own.
//
// Exec runs "godl web", the one entry point that needs no terminal: the
// daemon starts if it isn't up, the web interface comes on, and the
// browser opens. %%U is deliberately absent — godl takes URLs, but a
// launcher passing one would need a terminal or a dialog to say where
// to save it, which the web page does better.
const entryTemplate = `[Desktop Entry]
Type=Application
Version=1.0
Name=godl
GenericName=Download Manager
Comment=Download files, videos and torrents in the background
Exec=%s web
Icon=%s
Terminal=false
StartupNotify=false
Categories=Network;FileTransfer;
Keywords=download;downloader;torrent;video;yt-dlp;webdav;
`

func dataHome() (string, error) {
	if v := os.Getenv("XDG_DATA_HOME"); v != "" {
		return v, nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".local", "share"), nil
}

func entryPath() (string, error) {
	dir, err := dataHome()
	if err != nil {
		return "", err
	}
	return filepath.Join(dir, "applications", Name+".desktop"), nil
}

func install() error {
	entry, err := entryPath()
	if err != nil {
		return err
	}
	exe, err := os.Executable()
	if err != nil {
		return err
	}
	// Resolved so an entry written from a symlink (or from a relative
	// invocation) still points at a real binary after the shell that
	// made it is gone.
	if resolved, err := filepath.EvalSymlinks(exe); err == nil {
		exe = resolved
	}

	if err := os.MkdirAll(filepath.Dir(entry), 0o755); err != nil {
		return err
	}
	if err := installIcons(); err != nil {
		return err
	}
	body := fmt.Sprintf(entryTemplate, exe, Name)
	if err := os.WriteFile(entry, []byte(body), 0o644); err != nil {
		return err
	}
	refresh()
	return nil
}

// installIcons unpacks the embedded icons into the hicolor theme. The
// app<size>.png names become <size>x<size>/apps/godl.png, which is the
// layout icon lookup actually searches; the SVG goes in scalable/ for
// sizes nothing else covers.
func installIcons() error {
	dir, err := dataHome()
	if err != nil {
		return err
	}
	theme := filepath.Join(dir, "icons", "hicolor")

	entries, err := icons.ReadDir("icons")
	if err != nil {
		return err
	}
	for _, e := range entries {
		data, err := icons.ReadFile("icons/" + e.Name())
		if err != nil {
			return err
		}
		var dest string
		switch {
		case e.Name() == "godl.svg":
			dest = filepath.Join(theme, "scalable", "apps", Name+".svg")
		case strings.HasPrefix(e.Name(), "app"):
			size := strings.TrimSuffix(strings.TrimPrefix(e.Name(), "app"), ".png")
			dest = filepath.Join(theme, size+"x"+size, "apps", Name+".png")
		default:
			continue
		}
		if err := os.MkdirAll(filepath.Dir(dest), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(dest, data, 0o644); err != nil {
			return err
		}
	}
	return nil
}

func remove() error {
	entry, err := entryPath()
	if err != nil {
		return err
	}
	if err := os.Remove(entry); err != nil && !os.IsNotExist(err) {
		return err
	}
	dir, err := dataHome()
	if err != nil {
		return err
	}
	theme := filepath.Join(dir, "icons", "hicolor")
	// Only godl's own icon files are removed, never the size
	// directories: they are shared with every other application's
	// icons.
	for _, p := range iconPaths(theme) {
		if err := os.Remove(p); err != nil && !os.IsNotExist(err) {
			return err
		}
	}
	refresh()
	return nil
}

func iconPaths(theme string) []string {
	var out []string
	entries, err := icons.ReadDir("icons")
	if err != nil {
		return nil
	}
	for _, e := range entries {
		if e.Name() == "godl.svg" {
			out = append(out, filepath.Join(theme, "scalable", "apps", Name+".svg"))
			continue
		}
		size := strings.TrimSuffix(strings.TrimPrefix(e.Name(), "app"), ".png")
		out = append(out, filepath.Join(theme, size+"x"+size, "apps", Name+".png"))
	}
	return out
}

// refresh nudges the desktop into noticing the change. Both tools are
// best-effort: they are missing on minimal systems, and every desktop
// also picks the entry up on its own eventually — this is only so the
// icon appears now rather than after a re-login.
func refresh() {
	dir, err := dataHome()
	if err != nil {
		return
	}
	exec.Command("update-desktop-database", filepath.Join(dir, "applications")).Run()
	exec.Command("gtk-update-icon-cache", "-f", "-t", filepath.Join(dir, "icons", "hicolor")).Run()
}

func status() (bool, string, error) {
	entry, err := entryPath()
	if err != nil {
		return false, "", err
	}
	_, statErr := os.Stat(entry)
	if statErr != nil && !os.IsNotExist(statErr) {
		return false, entry, statErr
	}
	return statErr == nil, entry, nil
}
